      "\u670D\u52A1\u7AEF\u8FD4\u56DE\u4E86\u5B64\u7ACB\u8282\u70B9": "\u30B5\u30FC\u30D0\u30FC\u304C\u5B64\u7ACB\u3057\u305F\u30CE\u30FC\u30C9\u3092\u8FD4\u3057\u307E\u3057\u305F",
      "\u672A\u77E5\uFF1B\u7A7A\u5217\u8868\u4E0D\u80FD\u8BC1\u660E\u5DF2\u5F00\u542F\u68C0\u6D4B\uFF0C\u8BF7\u67E5\u8BE2 Project \u914D\u7F6E": "\u4E0D\u660E\u3002\u7A7A\u306E\u30EA\u30B9\u30C8\u306F\u76E3\u8996\u304C\u6709\u52B9\u3067\u3042\u308B\u3053\u3068\u3092\u8A3C\u660E\u3057\u307E\u305B\u3093\u3002\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u8A2D\u5B9A\u306E\u8AAD\u307F\u53D6\u308A",
      "\u62D3\u6251\u8B66\u793A\uFF1A{0}\uFF1B\u591A\u7236\u5173\u7CFB\u4FDD\u7559\uFF0C\u73AF\u8DEF\u8282\u70B9\u53EA\u5C55\u793A\u4E00\u6B21\u3002": "\u30C8\u30DD\u30ED\u30B8\u30FC\u306E\u8B66\u544A: {0};\u8907\u6570\u306E\u89AA\u304C\u4FDD\u6301\u3055\u308C\u3001\u30B5\u30A4\u30AF\u30EB \u30CE\u30FC\u30C9\u304C 1 \u56DE\u8868\u793A\u3055\u308C\u307E\u3059\u3002",
      "\u8D44\u6E90\u6811\u67E5\u8BE2\u5931\u8D25\uFF1B\u4E0D\u662F\u7A7A\u7ED3\u679C\u3002": "\u30EA\u30BD\u30FC\u30B9\u30C4\u30EA\u30FC\u306E\u30AF\u30A8\u30EA\u304C\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u3053\u308C\u306F\u7A7A\u306E\u7D50\u679C\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "\u6B63\u5728\u67E5\u8BE2\u5E94\u7528\u4E8B\u4EF6\u2026": "\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3\u30A4\u30D9\u30F3\u30C8\u3092\u8AAD\u307F\u53D6\u308A\u4E2D\u2026",
      "\u5E94\u7528\u4E8B\u4EF6\u67E5\u8BE2\u5931\u8D25\uFF1B\u4E0D\u662F\u6CA1\u6709\u4E8B\u4EF6\u3002": "\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3 \u30A4\u30D9\u30F3\u30C8 \u30AF\u30A8\u30EA\u304C\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u3053\u308C\u306F\u30A4\u30D9\u30F3\u30C8\u304C\u5B58\u5728\u3057\u306A\u3044\u3068\u3044\u3046\u610F\u5473\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "Project \u672A\u5F00\u542F\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\uFF1B\u6CA1\u6709\u5B64\u7ACB\u8282\u70B9\u4E0D\u662F\u6CA1\u6709\u5B64\u7ACB\u8D44\u6E90\u7684\u8BC1\u660E\u3002": "\u3053\u306E\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u3067\u306F\u5B64\u7ACB\u76E3\u8996\u306F\u7121\u52B9\u306B\u306A\u3063\u3066\u3044\u307E\u3059\u3002\u5B64\u7ACB\u3057\u305F\u30CE\u30FC\u30C9\u304C\u306A\u3044\u3053\u3068\u306F\u3001\u5B64\u7ACB\u3057\u305F\u30EA\u30BD\u30FC\u30B9\u304C\u306A\u3044\u3053\u3068\u3092\u8A3C\u660E\u3059\u308B\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "Project \u5DF2\u5F00\u542F\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\uFF1Bwarn={0}\u3002": "\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u306E\u5B64\u7ACB\u76E3\u8996\u304C\u6709\u52B9\u306B\u306A\u3063\u3066\u3044\u307E\u3059\u3002\u8B66\u544A={0}\u3002",
      "\u5B64\u7ACB\u8D44\u6E90\u68C0\u6D4B\u914D\u7F6E\u672A\u77E5\uFF1BProject \u914D\u7F6E\u8BFB\u53D6\u5931\u8D25\u3002": "\u5B64\u7ACB\u76E3\u8996\u8A2D\u5B9A\u306F\u4E0D\u660E\u3067\u3059\u3002\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u8A2D\u5B9A\u3092\u8AAD\u307F\u53D6\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
      "UID {0} \xB7 \u7236\u8282\u70B9 {1} \xB7 \u955C\u50CF {2}": "UID {0} \xB7 \u89AA {1} \xB7 \u753B\u50CF {2}",
