      "\u6B63\u5728\u8BFB\u53D6\u8D44\u6E90\u4E8B\u4EF6\u2026": "\u30EA\u30BD\u30FC\u30B9 \u30A4\u30D9\u30F3\u30C8\u3092\u8AAD\u307F\u53D6\u308A\u4E2D\u2026",
      "\u6B64\u90E8\u5206\u8BFB\u53D6\u5931\u8D25\uFF1B\u5176\u4ED6\u90E8\u5206\u7684\u6210\u529F\u4E0D\u4EE3\u8868\u672C\u90E8\u5206\u6210\u529F\u3002": "\u3053\u306E\u30BB\u30AF\u30B7\u30E7\u30F3\u306F\u30ED\u30FC\u30C9\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u4ED6\u306E\u6210\u529F\u3057\u305F\u30BB\u30AF\u30B7\u30E7\u30F3\u306F\u3001\u3053\u306E\u30BB\u30AF\u30B7\u30E7\u30F3\u304C\u6210\u529F\u3057\u305F\u3053\u3068\u3092\u8A3C\u660E\u3059\u308B\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "\u89C6\u56FE\u5DF2\u9690\u85CF\uFF0C\u67E5\u8BE2\u5DF2\u53D6\u6D88\uFF1B\u5DF2\u6709\u5185\u5BB9\u4E3A\u65E7\u5FEB\u7167\uFF0C\u4E0D\u4F1A\u81EA\u52A8\u6062\u590D\u67E5\u8BE2\u3002": "\u975E\u8868\u793A\u306B\u8868\u793A\u3057\u307E\u3059\u3002\u30AF\u30A8\u30EA\u306F\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F\u3002\u65E2\u5B58\u306E\u30B3\u30F3\u30C6\u30F3\u30C4\u306F\u53E4\u3044\u30B9\u30CA\u30C3\u30D7\u30B7\u30E7\u30C3\u30C8\u3067\u3059\u3002\u30AF\u30A8\u30EA\u306F\u81EA\u52D5\u7684\u306B\u306F\u518D\u958B\u3055\u308C\u307E\u305B\u3093\u3002",
      "Secret \u5185\u5BB9\u3001\u6CE8\u89E3\u503C\u3001\u73AF\u5883\u53D8\u91CF\u5B57\u9762\u503C\u548C command/args \u5DF2\u9690\u85CF\uFF1B\u5176\u4ED6\u81EA\u5B9A\u4E49\u5B57\u6BB5\u4EC5\u4F5C\u5C3D\u529B\u8131\u654F\uFF0C\u4E0D\u4FDD\u8BC1\u53D1\u73B0\u6240\u6709\u79D8\u5BC6\u3002": "\u79D8\u5BC6\u306E\u5185\u5BB9\u3001\u6CE8\u91C8\u5024\u3001\u30EA\u30C6\u30E9\u30EB\u74B0\u5883\u5024\u3001\u304A\u3088\u3073\u30B3\u30DE\u30F3\u30C9/\u5F15\u6570\u306F\u4FDD\u7559\u3055\u308C\u307E\u3059\u3002\u4ED6\u306E\u30AB\u30B9\u30BF\u30E0 \u30D5\u30A3\u30FC\u30EB\u30C9\u306F\u6A5F\u5BC6\u30C7\u30FC\u30BF\u306E\u30D9\u30B9\u30C8\u30A8\u30D5\u30A9\u30FC\u30C8\u578B\u524A\u9664\u3092\u53D7\u3051\u53D6\u308A\u307E\u3059\u3002\u3059\u3079\u3066\u306E\u79D8\u5BC6\u3092\u691C\u51FA\u3067\u304D\u308B\u308F\u3051\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "\uFF1B\u4E0D\u662F\u7A7A\u6210\u529F\u3002": ";\u6210\u529F\u3057\u305F\u7A7A\u306E\u7D50\u679C\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      " \u670D\u52A1\u7AEF\u53EF\u80FD\u4E0D\u652F\u6301\u6B64\u7AEF\u70B9\uFF0C\u6216\u5BF9\u8C61\u5DF2\u5220\u9664/\u4E0D\u53EF\u89C1\uFF1B\u4E0D\u4F5C\u65E0\u4E8B\u4EF6\u63A8\u65AD\u3002": " \u30A8\u30F3\u30C9\u30DD\u30A4\u30F3\u30C8\u304C\u30B5\u30DD\u30FC\u30C8\u3055\u308C\u3066\u3044\u306A\u3044\u304B\u3001\u30AA\u30D6\u30B8\u30A7\u30AF\u30C8\u304C\u524A\u9664\u3055\u308C\u3066\u3044\u308B\u304B\u30A2\u30AF\u30BB\u30B9\u4E0D\u80FD\u3067\u3042\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\u30A4\u30D9\u30F3\u30C8\u304C\u5B58\u5728\u3057\u306A\u3044\u3068\u63A8\u6E2C\u3057\u306A\u3044\u3067\u304F\u3060\u3055\u3044\u3002",
      "\u5DF2\u8FC7\u671F/\u6682\u505C": "\u53E4\u3044/\u4E00\u6642\u505C\u6B62",
      "\u670D\u52A1\u7AEF canSync: {0}\uFF08\u53EA\u8BFB\u89C2\u5BDF\uFF09": "\u30B5\u30FC\u30D0\u30FC canSync: {0} (\u8AAD\u307F\u53D6\u308A\u5C02\u7528\u76E3\u8996)",
      "\u670D\u52A1\u7AEF Project \u6D3B\u8DC3\u7A97\u53E3\uFF08\u4E0D\u662F\u5E94\u7528 canSync \u5224\u5B9A\uFF09": "\u30B5\u30FC\u30D0\u30FC \u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u306E\u30A2\u30AF\u30C6\u30A3\u30D6\u306A\u30A6\u30A3\u30F3\u30C9\u30A6 (\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3 canSync \u3067\u306F\u306A\u3044)",
      "\u5E94\u7528\u540C\u6B65\u7A97\u53E3": "\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3\u540C\u671F\u30A6\u30A3\u30F3\u30C9\u30A6",
      "\u67E5\u8BE2\u5E94\u7528\u540C\u6B65\u7A97\u53E3\uFF08\u670D\u52A1\u7AEF\u5224\u5B9A\uFF09": "\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3\u540C\u671F\u30A6\u30A3\u30F3\u30C9\u30A6\u306E\u8AAD\u307F\u53D6\u308A (\u30B5\u30FC\u30D0\u30FC\u8A55\u4FA1)",
      "\u6B63\u5728\u8BFB\u53D6\u670D\u52A1\u7AEF\u7A97\u53E3\u5224\u5B9A\u2026": "\u30B5\u30FC\u30D0\u30FC\u30A6\u30A3\u30F3\u30C9\u30A6\u306E\u8A55\u4FA1\u3092\u8AAD\u307F\u53D6\u308A\u4E2D\u2026",
      "\u540C\u6B65\u7A97\u53E3\u4E0D\u53EF\u7528\uFF1B\u4E0D\u4F1A\u6839\u636E\u672C\u5730\u65F6\u95F4\u63A8\u65AD\u53EF\u540C\u6B65\u3002": "\u540C\u671F\u30A6\u30A3\u30F3\u30C9\u30A6\u306F\u4F7F\u7528\u3067\u304D\u307E\u305B\u3093\u3002\u73FE\u5730\u6642\u9593\u306F\u540C\u671F\u306E\u9069\u683C\u6027\u3092\u63A8\u6E2C\u3059\u308B\u305F\u3081\u306B\u4F7F\u7528\u3055\u308C\u307E\u305B\u3093\u3002",
      "\u7BA1\u7406\u57DF\u53EA\u8BFB\u89C2\u6D4B": "\u8AAD\u307F\u53D6\u308A\u5C02\u7528\u7BA1\u7406",
      "\u5404\u6A21\u5757\u72EC\u7ACB\u6309\u9700\u67E5\u8BE2\uFF1B\u65E0\u6743\u9650\u6216\u4E0D\u652F\u6301\u4E0D\u4F1A\u963B\u585E\u5E94\u7528\u89C2\u6D4B\u3002\u751F\u6210\u5668\u53C2\u6570\u503C\u3001\u6A21\u677F\u8868\u8FBE\u5F0F\u3001\u8FDE\u63A5\u9519\u8BEF\u6B63\u6587\u4E0E\u8BA4\u8BC1\u914D\u7F6E\u4E0D\u4F20\u8F93\u3002": "\u30E2\u30B8\u30E5\u30FC\u30EB\u306F\u30AA\u30F3\u30C7\u30DE\u30F3\u30C9\u3067\u500B\u5225\u306B\u30ED\u30FC\u30C9\u3055\u308C\u307E\u3059\u3002\u62D2\u5426\u3055\u308C\u305F\u30E2\u30B8\u30E5\u30FC\u30EB\u307E\u305F\u306F\u30B5\u30DD\u30FC\u30C8\u3055\u308C\u3066\u3044\u306A\u3044\u30E2\u30B8\u30E5\u30FC\u30EB\u306F\u30A2\u30D7\u30EA\u30B1\u30FC\u30B7\u30E7\u30F3\u3092\u30D6\u30ED\u30C3\u30AF\u3057\u307E\u305B\u3093\u3002\u30B8\u30A7\u30CD\u30EC\u30FC\u30BF\u30FC\u5024\u3001\u30C6\u30F3\u30D7\u30EC\u30FC\u30C8\u5F0F\u3001\u63A5\u7D9A\u30A8\u30E9\u30FC\u672C\u6587\u3001\u304A\u3088\u3073\u8A8D\u8A3C\u8A2D\u5B9A\u306F\u4FDD\u7559\u3055\u308C\u307E\u3059\u3002",
      "\u7BA1\u7406\u57DF\u6A21\u5757": "\u7BA1\u7406\u30E2\u30B8\u30E5\u30FC\u30EB",
