      "\u7BA1\u7406\u57DF\u8BE6\u60C5": "\u7BA1\u7406\u5185\u5BB9",
      "\u67E5\u8BE2\u7BA1\u7406\u57DF\uFF08\u53EA\u8BFB\uFF09": "\u7BA1\u7406\u30C7\u30FC\u30BF\u306E\u8AAD\u307F\u53D6\u308A",
